// RegisterHandlersOptions configures RegisterHandlersWithOptions.
type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.DELETE(options.BaseURL+"/api/session", wrapper.DeleteSession, options.OperationMiddlewares["deleteSession"]...)
	router.POST(options.BaseURL+"/api/session", wrapper.CreateSession, options.OperationMiddlewares["createSession"]...)
	router.GET(options.BaseURL+"/api/me", wrapper.GetCurrentUser, options.OperationMiddlewares["getCurrentUser"]...)
	router.GET(options.BaseURL+"/api/admin/users", wrapper.ListUserAccounts, options.OperationMiddlewares["listUserAccounts"]...)
	router.POST(options.BaseURL+"/api/admin/users", wrapper.CreateUserAccount, options.OperationMiddlewares["createUserAccount"]...)
	router.PATCH(options.BaseURL+"/api/admin/users/:user_id", wrapper.UpdateUserAccount, options.OperationMiddlewares["updateUserAccount"]...)
	router.PATCH(options.BaseURL+"/api/users/order", wrapper.ReorderUserAccounts, options.OperationMiddlewares["reorderUserAccounts"]...)
	router.GET(options.BaseURL+"/api/projects", wrapper.ListProjects, options.OperationMiddlewares["listProjects"]...)
	router.GET(options.BaseURL+"/api/projects/:project_id", wrapper.GetProject, options.OperationMiddlewares["getProject"]...)
	router.PATCH(options.BaseURL+"/api/admin/projects", wrapper.UpdateProjects, options.OperationMiddlewares["updateProjects"]...)
	router.POST(options.BaseURL+"/api/admin/resource-imports", wrapper.ImportResource, options.OperationMiddlewares["importResource"]...)
	router.GET(options.BaseURL+"/api/requests/:request_id/validation", wrapper.GetValidation, options.OperationMiddlewares["getValidation"]...)
	router.GET(options.BaseURL+"/api/requests/:request_id/validation/files", wrapper.GetValidationFiles, options.OperationMiddlewares["getValidationFiles"]...)
	router.GET(options.BaseURL+"/api/requests/:request_id/validation/artifacts", wrapper.GetValidationArtifacts, options.OperationMiddlewares["getValidationArtifacts"]...)
	router.GET(options.BaseURL+"/api/validation", wrapper.ListValidation, options.OperationMiddlewares["listValidation"]...)
	router.POST(options.BaseURL+"/api/projects/:project_id/validation", wrapper.CreateValidation, options.OperationMiddlewares["createValidation"]...)

}

